def next_smallest_palindrome(num: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def mirror_left_to_right(s: str) -> str:
        n = len(s)
        half = n // 2
        if n % 2 == 0:
            return s[:half] + s[:half][::-1]
        else:
            return s[:half+1] + s[:half][::-1]

    def decrement_middle(s: str) -> str:
        n = len(s)
        s_list = list(s)
        mid = (n - 1) // 2

        # Decrement the middle digit(s)
        while mid >= 0:
            if s_list[mid] > '0':
                s_list[mid] = str(int(s_list[mid]) - 1)
                if n % 2 == 0:
                    s_list[n - 1 - mid] = s_list[mid]
                else:
                    if mid != n - 1 - mid:
                        s_list[n - 1 - mid] = s_list[mid]
                break
            else:
                s_list[mid] = '9'
                if n % 2 == 0:
                    s_list[n - 1 - mid] = '9'
                else:
                    if mid != n - 1 - mid:
                        s_list[n - 1 - mid] = '9'
                mid -= 1

        # If we decremented past the first digit (e.g. 1000 -> 0999)
        if mid < 0:
            # This means number length will reduce by 1 and all digits are 9
            return '9' * (n - 1)
        return ''.join(s_list)

    s = str(num)
    if num <= 0:
        # For zero or negative numbers, no smaller palindrome in positive integers
        return -1

    # If the number is a single digit > 0, next smallest palindrome is just one less
    if len(s) == 1:
        return num - 1

    # First, create the palindrome by mirroring left to right
    pal = mirror_left_to_right(s)
    pal_num = int(pal)

    # If palindrome is >= num, we need to decrement the palindrome
    if pal_num >= num:
        # Decrement the middle and mirror again
        dec_s = decrement_middle(s)
        # In case decrement_middle returns all 9's of smaller length, just return that
        # Otherwise, mirror again
        if len(dec_s) < len(s):
            return int(dec_s)
        pal = mirror_left_to_right(dec_s)
        pal_num = int(pal)

    # Ensure palindrome is less than num
    if pal_num >= num:
        # If still not less, decrement again
        dec_s = decrement_middle(pal)
        if len(dec_s) < len(pal):
            return int(dec_s)
        pal = mirror_left_to_right(dec_s)
        pal_num = int(pal)

    return pal_num
