def substract_elements(data):
    if isinstance(data, Iterable) and not isinstance(data, (str, bytes)):
        data = list(data)
        if len(data) < 2:
            return type(data)()
        # If elements are also iterables, recurse element-wise
        if all(isinstance(el, Iterable) and not isinstance(el, (str, bytes)) for el in data):
            # Check all have the same length
            length = len(data[0])
            if not all(len(el) == length for el in data):
                raise ValueError("All nested iterables must be of the same length")
            return type(data)(substract_elements([data[i][j] for i in range(len(data))]) for j in range(length))
        else:
            # Compute differences at this level
            return type(data)(data[i+1] - data[i] for i in range(len(data)-1))
    else:
        raise TypeError("Input must be a nested iterable of numbers")
