def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # A helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...999 is 100...001
        return n + 2

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left = s[:half_len]
    odd = (length % 2 != 0)

    pal = make_palindrome(left, odd)
    if pal > n:
        return pal

    # Increment the left part and form palindrome again
    left_num = int(left) + 1
    left_str = str(left_num)

    # If increment causes length increase (e.g. 999 + 1 = 1000)
    if len(left_str) > len(left):
        # Means palindrome length increases by 1, e.g. 999 -> 1001
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left_str, odd)
