from math import gcd

def find_solution(a, b, n):
    """
    Find non-negative integers x, y such that a*x + b*y = n.
    Return (x, y) if solution exists, else None.
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    g = gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find one particular solution to a*x + b*y = g
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g_, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (g_, x, y)

    _, x0, y0 = extended_gcd(a, b)
    x0 *= n // g
    y0 *= n // g

    # General solution:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    # We want x,y >= 0

    # Let's find k range so that both x,y are non-negative
    b_div_g = b // g
    a_div_g = a // g

    # Inequalities:
    # x0 + k*b_div_g >= 0  => k >= -x0 / b_div_g
    # y0 - k*a_div_g >= 0  => k <= y0 / a_div_g

    # Because k must be integer, we find ceil and floor bounds:

    from math import ceil, floor

    k_min = ceil(-x0 / b_div_g) if b_div_g != 0 else float('-inf')
    k_max = floor(y0 / a_div_g) if a_div_g != 0 else float('inf')

    if k_min > k_max:
        return None

    # Pick any k in [k_min, k_max], for example k = k_min
    k = k_min
    x = x0 + k * b_div_g
    y = y0 - k * a_div_g

    if x >= 0 and y >= 0:
        return (x, y)
    else:
        return None
