def find_Max(arr):
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If array is not rotated
    if arr[low] < arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        # Check if mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which side to go
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[0]
