def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left_half = s[:half_len]
    odd_length = (length % 2 != 0)

    # Form the palindrome by mirroring left half
    palindrome = make_palindrome(left_half, odd_length)
    if palindrome > num:
        return palindrome

    # If palindrome <= num, increment the left half and form palindrome again
    left_num = int(left_half)
    left_num += 1
    left_half = str(left_num)

    # Handle cases where incrementing left half changes its length (e.g. 999 -> 1000)
    if len(left_half) > half_len:
        # This means the palindrome length increases by 1 (e.g. 999 -> 1001)
        return int('1' + ('0' * (length - 1)) + '1')

    palindrome = make_palindrome(left_half, odd_length)
    return palindrome
```

