def get_total_number_of_sequences(n: int, m: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length, prev):
        if length == n:
            return 1
        total = 0
        start = prev * 2
        for next_elem in range(start, m + 1):
            total += count_sequences(length + 1, next_elem)
        return total

    total_sequences = 0
    for first_elem in range(1, m + 1):
        total_sequences += count_sequences(1, first_elem)

    return total_sequences
